  "max_tokens": 4096,
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "document",
          "source": {
            "type": "base64",
            "media_type": "application/pdf",
            "data": "{{ $json.pdf_base64 }}"
          }
        },
        {
          "type": "text",
          "text": "Du bekommst ein ausgefülltes Antragsformular der Stadt Würzburg (Altenhilfeplan Nr. 2, Antrag auf Zuschuss für Altentagesstätten). Das Formular kann maschinell ausgefüllt sein ODER handschriftlich. Extrahiere ALLE ausgefüllten Felder als striktes JSON nach folgendem Schema. Wenn ein Feld leer/nicht lesbar ist, setze null. Bei Beträgen: nur die Zahl als float (z.B. 1250.50), keine Währung, kein Tausender-Punkt. IBAN/BIC trimmen, ohne Leerzeichen. Antwort NUR als JSON-Objekt, keine Erklärung davor oder danach, kein Code-Fence. WICHTIG zur Pflicht: die Verwaltungspraxis der Stadt Würzburg verlangt Telefon, Bankverbindung (Bankname) und BIC IMMER — auch wenn das PDF kein Sternchen zeigt. Wenn du die Felder im PDF nicht findest, suche sorgfältig (häufig handschriftlich am Rand oder im Briefkopf).

Schema:
{
  "haushaltsjahr": integer | null,
  "name": string | null,                    // Name der Einrichtung
  "traeger": string | null,                 // Trägerverein/Organisation
  "strasse": string | null,
  "hausnummer": string | null,
  "plz": string | null,                      // 5-stellig
  "ort": string | null,
  "bankverbindung": string | null,           // Bankname — Verwaltungspraxis: Pflicht
  "iban": string | null,
  "bic": string | null,                      // Verwaltungspraxis: Pflicht (auch DE-IBAN)
  "ansprechpartner": string | null,
  "telefon": string | null,                  // Verwaltungspraxis: Pflicht (für Rückfragen)
  "email": string | null,
  "betriebskosten_vorjahr_euro": float | null,
  "personalkosten_vorjahr_euro": float | null,
  "monatliche_miete_euro": float | null,     // PDF fragt MONATLICH ab; nicht selbst × 12 rechnen
  "raeume_vorhanden": "ja" | "nein" | null,
  "raeume_unentgeltlich": "ja" | "nein" | null,
  "antragsdatum": string | null              // ISO YYYY-MM-DD
}"
        }
      ]
    }
  ]
}

