// Final-Sweep 2026-05-24: OCR-Daten werden NUR in antrag_einreichung.
// extrahiert_jsonb geparkt. Apl2.antraege erst beim finalen Bürger-Submit
// aus UE1 befüllt — saubere Vorlage-vs-Antrag-Trennung.
const input = $input.first().json;
const content = input.content?.[0]?.text;
if (!content) throw new Error('Claude lieferte keinen Text-Content: ' + JSON.stringify(input));
let extr;
try {
  const cleaned = content.trim().replace(/^```json\n?/, '').replace(/\n?```$/, '');
  extr = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude-Antwort ist kein JSON: ' + content.slice(0, 500));
}
// Defaults für UE1-Prefill: Status + Sprache
extr.submitted_language = 'de';
if (!extr.antragsdatum) extr.antragsdatum = new Date().toISOString().slice(0, 10);
// foerderbereich + geforderte_foerdersumme bleiben null — Sachbearbeitung beziffert
// Bemessungsfelder bleiben null — PDF fragt sie nicht ab
// oeffnungszeiten kommen aus dem Wochenplan-Branch (separater Node merged sie rein)
return [{
  json: {
    extrahiert: extr,
    einreichung_id: $('Webhook Trigger (Supabase NOTIFY)').first().json.body.einreichung_id
  }
}];
